#include <bits/stdc++.h>

using namespace std;

int main(void){
	int n,m,k;
	int a,b,cnt;
	bool solved[10][10]={};
	bool recorded[10]={};
	vector<int>ans;

	cin>>n>>m>>k;
	for(int ievent=0;ievent<k;ievent++){
		cin>>a>>b;
		solved[a-1][b-1]=true;
		for(int i=0;i<n;i++){
			cnt=0;
			for(int j=0;j<m;j++){
				if(solved[i][j])cnt++;
			}
			if((cnt==m)&&(!recorded[i])){
				ans.push_back(i+1);
				recorded[i]=true;
			}
		}
	}

	int sz=ans.size();
	for(int i=0;i<sz;i++){
		cout<<ans[i];
		if(i<(sz-1))cout<<" ";
		else cout<<endl;
	}
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(void){
	int n,m,k;
	int a,b;
	int cnt[10]={};
	vector<int>ans;

	cin>>n>>m>>k;
	for(int i=0;i<k;i++){
		cin>>a>>b;
		cnt[a-1]++;
		if(cnt[a-1]==m)ans.push_back(a);
	}

	int sz=ans.size();
	for(int i=0;i<sz;i++){
		cout<<ans[i];
		if(i<(sz-1))cout<<" ";
		else cout<<endl;
	}
	return 0;
}

n,m,k=map(int, input().split())

solved=[[False for j in range(m)]for i in range(n)]
recorded=[False for i in range(n)]
ans=[]

for ievent in range(k):
    a,b=map(int, input().split())
    solved[a-1][b-1]=True
    for i in range(n):
        cnt=0
        for j in range(m):
            if solved[i][j]:
                cnt+=1
        if cnt==m and recorded[i]==False:
            ans.append(i+1)
            recorded[i]=True

print(*ans)
